#include "../runtime/choices.h"
#include <iostream>
#include <stdexcept>
using namespace mahoyo::choices;
static int checks;static void check(bool v,const char*m){++checks;if(!v)throw std::runtime_error(m);}template<class F>void rejects(F f){bool yes=false;try{f();}catch(const std::exception&){yes=true;}check(yes,"invalid input rejected");}
int main(){try{Controller a;check(a.safe(),"initial empty safe");a.append(9,"a");a.append(3,"b");a.append(11,"c");check(!a.safe(),"queued list is not saved");a.beginText({}, {"A","B","C"});auto token=std::to_string(a.state()->revision);check(!a.select(token,1,true),"scene-ready barrier required");a.prepared();auto selected=a.select(token,1,true);check(selected&&selected->value==3,"ordinal maps owned itemvalue");check(!a.select(token,1,false)&&!a.select(token,-1,true)&&!a.select("old",1,true)&&!a.select(token,3,true),"paused/stale/outofrange rejected");a.complete(selected->revision);check(a.safe()&&!a.select(token,1,true),"161 normal clears list and token");Controller b;b.append(1,"x");b.beginText({}, {"X"});b.prepared();check(std::to_string(b.state()->revision)!=token,"tokens unique across Runtime controllers");b.reset();check(b.safe(),"scene discard resets without result");rejects([&]{a.beginText({},{});});rejects([&]{Controller::validateRequest({2,0,3,0});});rejects([&]{Controller::validateRequest({1,0,2,0});});rejects([&]{a.append(1,std::string("\x82\xa0",2));});check(validUtf8("日本語😀")&&!validUtf8(std::string("\xed\xa0\x80",3)),"strictUnicode noACP");std::vector<Layout> layout;for(int i=0;i<14;++i){Layout l;l.slot=i;l.enabled=1;layout.push_back(l);}a.append(99,"retained");a.beginWik({},layout);a.prepared();for(int i=0;i<14;++i)check(a.select(std::to_string(a.state()->revision),i,true)->value==i,"164 directslot index");a.complete(a.state()->revision);check(a.queued().size()==1&&!a.safe(),"164 doesnot clear160 queue");rejects([&]{a.beginWik({},{});});std::cout<<"choice controller: "<<checks<<" checks passed\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
